CREATE TABLE platform_configs (id varchar(64) PRIMARY KEY,config_key varchar(255) NOT NULL,name text NOT NULL,category varchar(255) NOT NULL DEFAULT '',value json NOT NULL,description text NOT NULL,is_public boolean NOT NULL DEFAULT false,status varchar(32) NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY platform_configs_key_unique(config_key),KEY platform_configs_public_idx(is_public,status,category));
